        RAISE EXCEPTION 'B.2 initialization refused: unsupported schema version';
    END IF;
    IF (SELECT count(*) FROM pg_catalog.pg_class c
        JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p')) <> 9 THEN
        RAISE EXCEPTION 'B.2 initialization refused: unexpected public table set';
    END IF;
    FOREACH expected_name IN ARRAY ARRAY[
        'diagnoses', 'equipment', 'equipment_ticket_counts', 'postgres_schema',
        'request_budgets', 'snapshot_chunks', 'snapshot_manifests', 'ticket_history', 'tickets'
    ] LOOP
        IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c
                       JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
                       WHERE n.nspname = 'public' AND c.relname = expected_name AND c.relkind = 'r') THEN
            RAISE EXCEPTION 'B.2 initialization refused: missing expected table %', expected_name;
        END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_class c
               JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
               WHERE n.nspname <> 'public' AND n.nspname <> 'information_schema' AND n.nspname !~ '^pg_') THEN
        RAISE EXCEPTION 'B.2 initialization refused: unexpected non-public relations';
    END IF;
END;
$b2_existing_guard$;
\endif

