DO $b2_seed_validation$
BEGIN
    IF (SELECT count(*) FROM public.postgres_schema) <> 1 THEN
        RAISE EXCEPTION 'B.2 seed validation failed: unexpected row count for postgres_schema';
    END IF;
    IF (SELECT count(*) FROM public.equipment) <> 2 THEN
        RAISE EXCEPTION 'B.2 seed validation failed: unexpected row count for equipment';
    END IF;
    IF (SELECT count(*) FROM public.diagnoses) <> 1 THEN
        RAISE EXCEPTION 'B.2 seed validation failed: unexpected row count for diagnoses';
    END IF;
    IF (SELECT count(*) FROM public.tickets) <> 1 THEN
        RAISE EXCEPTION 'B.2 seed validation failed: unexpected row count for tickets';
    END IF;
    IF (SELECT count(*) FROM public.ticket_history) <> 2 THEN
        RAISE EXCEPTION 'B.2 seed validation failed: unexpected row count for ticket_history';
    END IF;
    IF (SELECT count(*) FROM public.request_budgets) <> 0 THEN
        RAISE EXCEPTION 'B.2 seed validation failed: unexpected row count for request_budgets';
    END IF;
    IF (SELECT count(*) FROM public.snapshot_manifests) <> 0 THEN
        RAISE EXCEPTION 'B.2 seed validation failed: unexpected row count for snapshot_manifests';
    END IF;
    IF (SELECT count(*) FROM public.snapshot_chunks) <> 0 THEN
        RAISE EXCEPTION 'B.2 seed validation failed: unexpected row count for snapshot_chunks';
    END IF;
    IF (SELECT count(*) FROM public.equipment_ticket_counts) <> 2 THEN
        RAISE EXCEPTION 'B.2 seed validation failed: unexpected row count for equipment_ticket_counts';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.diagnoses
        WHERE id = 'D-b72ecee0befca3b36c6c9ad9'
          AND pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(snapshot, 'UTF8')), 'hex')
              = 'c37067b9c3f3a27e8aeda4af51901bf08591e24c3298c5ec3df32ecda857a03d'
    ) THEN
        RAISE EXCEPTION 'B.2 seed validation failed: computed diagnosis differs';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.tickets
        WHERE id = 'T-SEED-001' AND equipment_id = 'R-01'
          AND diagnosis_id = 'D-b72ecee0befca3b36c6c9ad9'
          AND status = 'Resolved' AND version = 1
    ) THEN
        RAISE EXCEPTION 'B.2 seed validation failed: historical ticket differs';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.equipment_ticket_counts WHERE equipment_id = 'R-01' AND total = 1)
       OR NOT EXISTS (SELECT 1 FROM public.equipment_ticket_counts WHERE equipment_id = 'CELL-01' AND total = 0) THEN
        RAISE EXCEPTION 'B.2 seed validation failed: equipment counts differ';
    END IF;
    IF (SELECT count(*) FROM public.ticket_history WHERE ticket_id = 'T-SEED-001' AND version = 1 AND kind = 'created') <> 1
       OR (SELECT count(*) FROM public.ticket_history WHERE ticket_id = 'T-SEED-001' AND version = 1 AND kind = 'status') <> 1 THEN
